const sourceCollator=new Intl.Collator('fr',{sensitivity:'base',numeric:true});
function sortSourceRows(){let list=$('.engine-list');if(!list)return;let rows=[...list.children].filter(item=>item.matches('.engine'));rows.sort((a,b)=>sourceCollator.compare(a.querySelector('b')?.textContent.trim()||a.textContent.trim(),b.querySelector('b')?.textContent.trim()||b.textContent.trim())).forEach(row=>list.appendChild(row))}
