function render(data,append=false){
  currentResults=append?currentResults.concat(data.results):data.results.slice();
  let operatorCount=(data.operators?.phrases?.length||0)+(data.operators?.excluded?.length||0)+Boolean(data.operators?.site)+Boolean(data.operators?.filetype);
  $('#status').innerHTML=`${data.shown} résultat${data.shown>1?'s':''} affiché${data.shown>1?'s':''} · sources fusionnées et dédupliquées${data.ranking?.latest?' · veille chronologique':data.ranking?.diversified?' · classement diversifié':''}${operatorCount?' · '+operatorCount+' opérateur'+(operatorCount>1?'s':'')+' actif'+(operatorCount>1?'s':''):''}${data.cache?.hit?'<span class="cache-hit">cache local</span>':''}`;
  $('#warnings').innerHTML=data.warnings.map(w=>`<span class="warning">${esc(w)}</span>`).join(' · ');
  $('#results').className='results'+(category==='images'?' images':'');
  data.results.forEach(r=>resultItems.set(r.url,r));
  let html=data.results.map(r=>category==='images'&&r.image_url?`<article class="result image-card" data-result-url="${esc(r.url)}" data-image-result="1"><a href="${esc(r.url)}" target="_blank" rel="noopener"><img src="${esc(r.image_url)}" alt="${esc(r.title)}" loading="lazy"><div><span class="badge">${esc(r.engine)}</span><h2>${esc(r.title)}</h2></div></a><button class="favorite-btn image-fav ${r.favorite?'active':''}" type="button" data-url="${esc(r.url)}" aria-label="${r.favorite?'Retirer des':'Ajouter aux'} favoris">${r.favorite?'♥':'♡'}</button><button class="preview-btn image-preview" type="button" data-preview-url="${esc(r.url)}" title="Figer cet aperçu">Aperçu</button></article>`:`<article class="result ${category==='all'?'mixed-result':''} ${category==='all'&&r.image_url?'mixed-with-thumbnail':''}" data-result-url="${esc(r.url)}">${category==='all'&&r.image_url?`<img class="mixed-thumbnail" src="${esc(r.image_url)}" alt="" loading="lazy">`:''}<div><div class="result-source"><span class="badge">${esc(r.engine)}</span>${category==='all'?`<span class="content-type">${esc(({web:'Web',images:'Image',videos:'Vidéo',news:'Actualité',books:'Livre'})[r.category]||r.category)}</span>`:''}<span>${esc(new URL(r.url).hostname)}</span>${r.published_at?publishedLabel(r.published_at):''}</div><a href="${esc(r.url)}" target="_blank" rel="noopener"><h2>${esc(r.title)}</h2></a><p>${esc(r.snippet)}</p>${relatedGroup(r)}</div><div class="result-actions"><button class="favorite-btn ${r.favorite?'active':''}" type="button" data-url="${esc(r.url)}" aria-label="${r.favorite?'Retirer des':'Ajouter aux'} favoris">${r.favorite?'♥':'♡'}</button><button class="preview-btn" type="button" data-preview-url="${esc(r.url)}" title="Figer cet aperçu">Aperçu</button>${scoreBreakdown(r)}</div></article>`).join('');
  if(append)$('#results').insertAdjacentHTML('beforeend',html);else $('#results').innerHTML=html||'<div class="empty"><h2>Aucun résultat</h2><p>Essaie de modifier les filtres ou la requête.</p></div>';
  $('#loadMore').classList.toggle('visible',data.has_more);$('#loadMore').disabled=false;$('#loadMore').innerHTML='Afficher davantage <span>↓</span>';
  $('#exportBar').classList.toggle('visible',currentResults.length>0);
  attachFavoriteHandlers();
  attachPreviewHandlers();
  loadSourceHealth();
}
