const healthLabels={ok:'Disponible',slow:'Ralentie',empty:'Réponse vide',error:'En erreur',unknown:'Pas encore testée',disabled:'Désactivée'};
function healthAge(value){if(!value)return 'Jamais vérifiée';let seconds=Math.max(0,Math.round((Date.now()-new Date(value).getTime())/1000));if(seconds<60)return 'À l’instant';if(seconds<3600)return `Il y a ${Math.round(seconds/60)} min`;if(seconds<86400)return `Il y a ${Math.round(seconds/3600)} h`;return `Il y a ${Math.round(seconds/86400)} j`}
function healthDetail(item){if(item.status==='error'&&item.error_message)return `${item.error_message} · Dernier succès : ${healthAge(item.last_success).toLowerCase()}`;if(item.last_error&&item.error_message)return `${healthAge(item.checked_at)} · Dernière erreur : ${item.error_message}`;return healthAge(item.checked_at)}
function inlineHealthLabel(item){if(item.status==='disabled')return'Désactivée';if(item.status==='unknown')return'Non testée';if(item.status==='error')return'Erreur';if(item.status==='empty')return'Aucun résultat';if(item.average_ms!=null)return`${item.average_ms} ms${item.status==='slow'?' · lent':''}`;return healthLabels[item.status]||item.status}
function updateInlineSourceHealth(items){items.forEach(item=>{let dot=$(`[data-engine-health-dot="${CSS.escape(item.key)}"]`),metric=$(`[data-engine-health-metric="${CSS.escape(item.key)}"]`),row=$(`[data-engine-row="${CSS.escape(item.key)}"]`);if(!dot||!metric)return;dot.className=`engine-inline-dot state-${item.status}`;metric.className=`engine-inline-metric ${item.status==='error'?'error':['slow','empty'].includes(item.status)?'problem':''}`;metric.textContent=`: ${inlineHealthLabel(item)}`;let detail=`${healthLabels[item.status]||item.status} · ${healthDetail(item)}`;if(item.result_count&&item.status!=='disabled')detail+=` · ${item.result_count} résultat${item.result_count>1?'s':''} au dernier test`;row.title=detail})}
function updatePreferenceHealthState(data){let badge=$('#settingsHealthBadge');badge.className=data.overall||'unknown';badge.parentElement.title=data.overall==='healthy'?'Préférences · sources disponibles':data.overall==='warning'?'Préférences · certaines sources demandent votre attention':data.overall==='down'?'Préférences · sources indisponibles':'Préférences · sources non testées';$$('[data-pref-view="health"]').forEach(button=>{button.classList.toggle('attention',data.overall==='warning');button.classList.toggle('down',data.overall==='down')})}
