function attachPreviewHandlers(){
  $$('[data-preview-url]').forEach(button=>button.onclick=e=>{e.stopPropagation();openPreview(button.dataset.previewUrl,true)});
  if(!matchMedia('(hover:hover) and (pointer:fine)').matches)return;
  $$('[data-result-url]').forEach(card=>{card.onmouseenter=()=>{if(previewPinned)return;clearTimeout(previewTimer);previewTimer=setTimeout(()=>openPreview(card.dataset.resultUrl,false),card.dataset.imageResult?650:450)};card.onmouseleave=()=>clearTimeout(previewTimer)});
}
async function openPreview(url,pin=false){
  let local=resultItems.get(url),drawer=$('#previewDrawer');
  if(pin)previewPinned=true;
  if(!drawer.classList.contains('open')){closeDrawers();previewPinned=pin;drawer.classList.add('open');drawer.setAttribute('aria-hidden','false')}
  drawer.classList.toggle('pinned',previewPinned);$('#previewMode').textContent=previewPinned?'FIGÉ':'SURVOL';
  $('#overlay').classList.toggle('open',previewPinned);
  let request=++previewRequest;
  $('#previewContent').innerHTML='<div class="preview-loading">Lecture limitée des métadonnées…</div>';
  let data;try{data=await (await fetch(`/api/preview?url=${encodeURIComponent(url)}`)).json()}catch(e){data={ok:false,error:'Aperçu indisponible'}}
  if(request!==previewRequest)return;
  let isImage=local?.category==='images',title=isImage&&local?.title?local.title:data.ok&&data.title?data.title:local?.title||'Résultat',description=isImage&&local?.snippet?local.snippet:data.ok&&data.description?data.description:local?.snippet||'',excerpt=data.ok?data.excerpt||'':'',finalUrl=data.ok?data.canonical:url,domain='';try{domain=new URL(finalUrl).hostname}catch(e){}
  let visualUrl=isImage?(local.image_url||local.image_original_url):(data.ok?data.image_url:'');
  let image=visualUrl?`<div class="preview-visual ${isImage?'image-detail':''}"><img src="/api/preview-image?url=${encodeURIComponent(visualUrl)}" alt="${esc(isImage?local.title:'')}" loading="lazy"></div>`:'';
  let music=data.native==='musicbrainz'&&data.music?data.music:null;
  let scryfall=data.native==='scryfall'&&data.card?data.card:null;
  let unit=data.native==='openhammer'&&data.unit?data.unit:null;
  if(scryfall){let pictures=scryfall.faces.filter(face=>face.image_url);image=pictures.length?`<div class="card-gallery ${pictures.length>1?'multiple':''}">${pictures.map(face=>`<img src="/api/preview-image?url=${encodeURIComponent(face.image_url)}" alt="${esc(face.name)}" loading="lazy">`).join('')}</div>`:''}
  let musicDetails=music?`<section class="music-details">${music.artist?`<span><b>Artiste</b>${esc(music.artist)}</span>`:''}${music.release_date?`<span><b>Première parution</b>${esc(music.release_date)}</span>`:''}${music.primary_type?`<span><b>Format</b>${esc(music.primary_type)}${music.secondary_types?.length?` · ${esc(music.secondary_types.join(', '))}`:''}</span>`:''}${music.labels?.length?`<span><b>Label</b>${esc(music.labels.join(', '))}</span>`:''}${music.country?`<span><b>Pays de l’édition</b>${esc(music.country)}</span>`:''}${music.release_count?`<span><b>Éditions répertoriées</b>${music.release_count}</span>`:''}</section>${music.genres?.length?`<div class="music-genres">${music.genres.map(genre=>`<span>${esc(genre)}</span>`).join('')}</div>`:''}${music.tracks?.length?`<section class="track-list"><b>Morceaux de l’édition retenue${music.track_count?` · ${music.track_count}`:''}</b><ol>${music.tracks.map(track=>`<li><span>${esc(track.position)}</span>${esc(track.title)}</li>`).join('')}</ol>${music.track_count>music.tracks.length?`<small>${music.track_count-music.tracks.length} autre${music.track_count-music.tracks.length>1?'s':''} morceau${music.track_count-music.tracks.length>1?'x':''} dans l’édition</small>`:''}</section>`:''}`:'';
  let cardDetails=scryfall?`<section class="card-facts"><span><b>Extension</b>${esc(scryfall.set_name)} · ${esc(String(scryfall.set_code).toUpperCase())}</span><span><b>Collection</b>N° ${esc(scryfall.collector_number)} · ${esc(scryfall.rarity)}</span>${scryfall.released_at?`<span><b>Parution</b>${esc(scryfall.released_at)}</span>`:''}${scryfall.artist?`<span><b>Illustration</b>${esc(scryfall.artist)}</span>`:''}</section>${scryfall.faces.map(face=>`<section class="card-face"><header><b>${esc(face.name)}</b>${face.mana_cost?`<span>${esc(face.mana_cost)}</span>`:''}</header>${face.type_line?`<small>${esc(face.type_line)}</small>`:''}${face.text?`<p>${esc(face.text)}</p>`:''}${face.flavor_text?`<blockquote>${esc(face.flavor_text)}</blockquote>`:''}${face.stats?`<strong>${esc(face.stats)}</strong>`:face.loyalty?`<strong>Loyauté ${esc(face.loyalty)}</strong>`:face.defense?`<strong>Défense ${esc(face.defense)}</strong>`:''}</section>`).join('')}${scryfall.legalities?.length?`<section class="card-legality"><b>Formats autorisés</b><div>${scryfall.legalities.map(format=>`<span>${esc(format)}</span>`).join('')}</div></section>`:''}${Object.values(scryfall.prices||{}).some(Boolean)?`<section class="card-prices"><b>Prix indicatifs Scryfall</b>${scryfall.prices.eur?`<span>${esc(scryfall.prices.eur)} €</span>`:''}${scryfall.prices.eur_foil?`<span>Foil ${esc(scryfall.prices.eur_foil)} €</span>`:''}${scryfall.prices.usd?`<span>${esc(scryfall.prices.usd)} $</span>`:''}</section>`:''}`:'';
  let weaponTable=(label,weapons)=>weapons?.length?`<section class="unit-weapons"><b>${label}</b><div class="unit-table"><table><thead><tr><th>Arme</th><th>Portée</th><th>A</th><th>CT/CC</th><th>F</th><th>PA</th><th>D</th></tr></thead><tbody>${weapons.map(weapon=>`<tr><td><strong>${esc(weapon.name)}</strong>${weapon.Keywords&&weapon.Keywords!=='-'?`<small>${esc(weapon.Keywords)}</small>`:''}</td><td>${esc(weapon.Range||'—')}</td><td>${esc(weapon.A||'—')}</td><td>${esc(weapon.BS||weapon.WS||'—')}</td><td>${esc(weapon.S||'—')}</td><td>${esc(weapon.AP||'—')}</td><td>${esc(weapon.D||'—')}</td></tr>`).join('')}</tbody></table></div></section>`:'';
  let unitDetails=unit?`<section class="unit-summary"><span><b>Faction</b>${esc(unit.faction)}</span><span><b>Édition</b>${esc(unit.edition.replace('e','e édition'))}</span>${unit.points?.base!=null?`<span><b>Coût de base</b>${esc(unit.points.base)} points</span>`:''}${unit.composition?.min_models?`<span><b>Composition</b>${esc(unit.composition.min_models)}${unit.composition.max_models&&unit.composition.max_models!==unit.composition.min_models?` à ${esc(unit.composition.max_models)}`:''} figurine${unit.composition.max_models>1?'s':''}</span>`:''}${unit.invuln_save?`<span><b>Sauvegarde invulnérable</b>${esc(unit.invuln_save)}</span>`:''}</section><section class="unit-stats">${['M','T','SV','W','LD','OC'].filter(key=>unit.stats?.[key]).map(key=>`<span><b>${key}</b>${esc(unit.stats[key])}</span>`).join('')}</section>${unit.points?.variants?.length?`<section class="unit-variants"><b>Variantes</b>${unit.points.variants.map(item=>`<span>${esc(item.name)} <strong>${esc(item.cost)} pts</strong></span>`).join('')}</section>`:''}${weaponTable('Armes de tir',unit.weapons?.ranged)}${weaponTable('Armes de mêlée',unit.weapons?.melee)}${unit.abilities?.length?`<section class="unit-abilities"><b>Aptitudes</b>${unit.abilities.map(ability=>`<article><strong>${esc(ability.name)}</strong><p>${esc(ability.description)}</p></article>`).join('')}</section>`:''}${unit.special_rules?.length?`<section class="unit-tags"><b>Règles spéciales</b><div>${unit.special_rules.map(rule=>`<span>${esc(rule)}</span>`).join('')}</div></section>`:''}${unit.keywords?.length?`<section class="unit-tags"><b>Mots-clés</b><div>${unit.keywords.map(keyword=>`<span>${esc(keyword)}</span>`).join('')}</div></section>`:''}`:'';
  let reading=musicDetails||cardDetails||unitDetails||(excerpt?`<section class="preview-excerpt"><b>À lire dans cette page</b><p>${esc(excerpt)}</p></section>`:'');
  let attribution=isImage&&(local.image_author||local.image_license)?`<section class="image-attribution">${local.image_author?`<span><b>Auteur ou crédit</b>${esc(local.image_author)}</span>`:''}${local.image_license?`<span><b>Licence</b>${local.image_license_url?`<a href="${esc(local.image_license_url)}" target="_blank" rel="noopener">${esc(local.image_license)}</a>`:esc(local.image_license)}</span>`:''}</section>`:'';
  let actions=isImage?`<div class="preview-actions"><a class="preview-open" href="${esc(finalUrl)}" target="_blank" rel="noopener">Ouvrir la page source ↗</a>${local.image_original_url?`<a class="preview-original" href="${esc(local.image_original_url)}" target="_blank" rel="noopener">Voir l’image originale</a>`:''}</div>`:`<a class="preview-open" href="${esc(finalUrl)}" target="_blank" rel="noopener">Ouvrir le résultat ↗</a>`;
  $('#previewContent').innerHTML=`<article class="preview-card ${music?'music-preview':''} ${scryfall?'scryfall-preview':''} ${unit?'unit-preview':''}">${image}<span class="preview-domain">${esc(data.site||domain)}</span><h3>${esc(title)}</h3><p class="preview-lead">${esc(description)||'Aucune description supplémentaire disponible.'}</p>${attribution}${reading}<div class="preview-meta"><span>${esc(local?.engine||'Source web')}</span><span>Score ${Math.round((local?.score||0)*100)}/100</span>${data.type?`<span>${esc(data.type)}</span>`:''}</div>${actions}<div class="preview-note">${music?'Fiche créée depuis les API publiques de MusicBrainz et Cover Art Archive. ':scryfall?'Fiche créée depuis l’API publique Scryfall. Les visuels de cartes appartiennent à leurs ayants droit. ':unit?'Données communautaires OpenHammer, non officielles et susceptibles d’évoluer. Vérifiez les règles et coûts dans les publications Games Workshop avant une partie ou un tournoi. ':data.native==='warhammerwiki'?'Article communautaire du Warhammer 40K Wiki. ':isImage?'L’image, sa légende et ses crédits proviennent de la page source. ':''}FitSearch n’exécute aucun script de la page. Survolez un autre résultat pour remplacer cet aperçu ; le bouton Aperçu le fige.</div>${!data.ok?`<div class="warning">${esc(data.error||'Aperçu distant indisponible')}</div>`:''}</article>`
  $$('#previewContent img').forEach(previewImage=>previewImage.onerror=()=>previewImage.remove());
}
$('#closePreview').onclick=closeDrawers;
let updatePoll=null;
async function refreshUpdateStatus(reloadWhenDone=false){try{let data=await (await fetch('/api/update-status')).json(),progress=$('#updateProgress');progress.className=`update-progress ${data.phase||'idle'}`;progress.querySelector('span').textContent=data.message||'Aucune mise à jour en cours';if(['queued','installing'].includes(data.phase)){clearTimeout(updatePoll);updatePoll=setTimeout(()=>refreshUpdateStatus(reloadWhenDone),1800)}else{$('.update-box').classList.remove('busy');if(data.phase==='complete'&&reloadWhenDone&&!data.restart_required)setTimeout(()=>location.reload(),3500)}}catch(e){if(reloadWhenDone){clearTimeout(updatePoll);updatePoll=setTimeout(()=>refreshUpdateStatus(true),2200)}}}
$('#updateFile').onchange=async event=>{let file=event.target.files[0];if(!file)return;if(!confirm('Installer cette archive FitSearch ? Une sauvegarde de vos données sera créée automatiquement.')){event.target.value='';return}let box=$('.update-box'),progress=$('#updateProgress');box.classList.add('busy');progress.className='update-progress queued';progress.querySelector('span').textContent='Vérification de l’archive…';let form=new FormData();form.append('file',file);try{let data=await (await fetch('/api/update',{method:'POST',body:form})).json();if(!data.ok)throw new Error(data.error||'Mise à jour impossible');progress.querySelector('span').textContent=`FitSearch ${data.version} vérifié · installation imminente…`;setTimeout(()=>refreshUpdateStatus(true),1000)}catch(error){box.classList.remove('busy');progress.className='update-progress error';progress.querySelector('span').textContent=error.message;event.target.value=''}};
$('#settingsBtn').addEventListener('click',()=>refreshUpdateStatus(false));
$('#restoreFile').onchange=async event=>{let file=event.target.files[0];if(!file)return;let message=$('#backupMessage');if(!confirm('Restaurer cette sauvegarde remplacera les données locales actuelles. Continuer ?')){event.target.value='';return}$('.backup-box').classList.add('busy');message.className='';message.textContent='Restauration en cours…';let form=new FormData();form.append('file',file);try{let data=await (await fetch('/api/restore',{method:'POST',body:form})).json();if(!data.ok)throw new Error(data.error||'Restauration impossible');message.className='success';message.textContent='Sauvegarde restaurée. Rechargement…';setTimeout(()=>location.reload(),700)}catch(error){message.className='error';message.textContent=error.message;$('.backup-box').classList.remove('busy');event.target.value=''}};
function setCredentialState(card,configured,source){let state=card.querySelector('.credential-state');state.className=`credential-state ${configured?'ready':source==='github'?'optional':'missing'}`;state.textContent=configured?'Configuré':source==='github'?'Sans clé':'Clé manquante'}
$$('[data-save-credential]').forEach(button=>button.onclick=async()=>{let source=button.dataset.saveCredential,card=button.closest('.credential-card'),message=card.querySelector('.credential-message'),form=new FormData();card.querySelectorAll('input').forEach(input=>form.append(input.name,input.value));button.disabled=true;button.textContent='Vérification…';message.className='credential-message';message.textContent='Connexion à la source…';try{let data=await (await fetch(`/api/credentials/${source}`,{method:'POST',body:form})).json();if(!data.ok)throw new Error(data.error||'Connexion refusée');setCredentialState(card,data.configured,source);card.querySelectorAll('input').forEach(input=>input.value='');message.className='credential-message success';message.textContent=data.message||'Connexion réussie';let toggle=$(`[data-engine="${source}"]`);if(toggle)toggle.checked=true;await loadSourceHealth()}catch(error){message.className='credential-message error';message.textContent=error.message}finally{button.disabled=false;button.textContent='Enregistrer et tester'}});
$$('[data-remove-credential]').forEach(button=>button.onclick=async()=>{let source=button.dataset.removeCredential,card=button.closest('.credential-card');if(!confirm(`Effacer les identifiants ${source} enregistrés sur cet ordinateur ?`))return;let data=await (await fetch(`/api/credentials/${source}/remove`,{method:'POST'})).json();if(data.ok){setCredentialState(card,false,source);card.querySelectorAll('input').forEach(input=>input.value='');let message=card.querySelector('.credential-message');message.className='credential-message success';message.textContent=source==='github'?'Jeton effacé · le mode sans clé reste disponible':source==='deepl'?'Clé DeepL effacée':'Identifiants effacés · source désactivée';let toggle=$(`[data-engine="${source}"]`);if(toggle&&source!=='github')toggle.checked=false;await loadSourceHealth()}});
let detectedTranslationLanguage='';
function setTranslationActions(enabled){['#copyTranslation','#useTranslation','#searchTranslation'].forEach(selector=>$(selector).disabled=!enabled)}
function openTranslator(){closeDrawers();let input=$('#translationInput');if(!input.value&&$('#query').value.trim())input.value=$('#query').value.trim();$('#translatorDrawer').classList.add('open');$('#overlay').classList.add('open');$('#translatorDrawer').setAttribute('aria-hidden','false');setTimeout(()=>input.focus(),180)}
$('#translatorBtn').onclick=openTranslator;
$('#closeTranslator').onclick=closeDrawers;
$('#configureDeepL').onclick=()=>{closeDrawers();openPreferenceView('credentials')};
$('#translateText').onclick=async()=>{let button=$('#translateText'),status=$('#translationStatus'),form=new FormData();form.append('text',$('#translationInput').value.trim());form.append('source',$('#translationSource').value);form.append('target',$('#translationTarget').value);button.disabled=true;button.textContent='Traduction…';status.className='translation-status';status.textContent='Connexion sécurisée à DeepL…';setTranslationActions(false);try{let data=await (await fetch('/api/translate',{method:'POST',body:form})).json();if(!data.ok)throw new Error(data.error||'Traduction impossible');$('#translationOutput').value=data.text;detectedTranslationLanguage=data.detected_source_language||$('#translationSource').value;status.className='translation-status success';status.textContent=`${data.provider}${detectedTranslationLanguage?' · langue détectée : '+detectedTranslationLanguage:''}`;setTranslationActions(true)}catch(error){$('#translationOutput').value='';status.className='translation-status error';status.textContent=error.message}finally{button.disabled=false;button.textContent='Traduire'}};
$('#swapTranslationLanguages').onclick=()=>{let source=$('#translationSource'),target=$('#translationTarget'),sourceCode=source.value||detectedTranslationLanguage;if(!sourceCode)return;let previousTarget=target.value;target.value=sourceCode;source.value=previousTarget;let input=$('#translationInput'),output=$('#translationOutput');if(output.value){let value=input.value;input.value=output.value;output.value=value;setTranslationActions(Boolean(output.value))}};
$('#copyTranslation').onclick=async()=>{let value=$('#translationOutput').value;if(!value)return;try{await navigator.clipboard.writeText(value);$('#translationStatus').textContent='Traduction copiée dans le presse-papiers'}catch(error){$('#translationOutput').select();document.execCommand('copy');$('#translationStatus').textContent='Traduction copiée dans le presse-papiers'}};
$('#useTranslation').onclick=()=>{let value=$('#translationOutput').value;if(!value)return;$('#query').value=value;closeDrawers();$('#query').focus()};
$('#searchTranslation').onclick=()=>{let value=$('#translationOutput').value;if(!value)return;$('#query').value=value;closeDrawers();$('#searchForm').requestSubmit()};
async function exportResults(format,button){if(!currentResults.length)return;button.disabled=true;let payload={format,query:$('#query').value.trim(),items:currentResults.map(({title,url,snippet,engine,category,score})=>({title,url,snippet,engine,category,score}))};try{let response=await fetch('/api/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw new Error('export');let blob=await response.blob(),disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="([^"]+)"/),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=match?match[1]:`fitsearch-export.${format}`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}finally{button.disabled=false}}
$$('[data-export]').forEach(button=>button.onclick=()=>exportResults(button.dataset.export,button));

const authDialog=$('#authDialog'),authMessage=$('#authMessage');
$('#accountBtn').onclick=()=>{authMessage.textContent='';authMessage.className='';authDialog.showModal();if(!authenticated)setTimeout(()=>$('#loginUsername').focus(),50)};
authDialog.querySelector('.dialog-close').onclick=()=>authDialog.close();
$('#loginForm').onsubmit=async event=>{event.preventDefault();if(authenticated)return;let form=new FormData();form.append('username',$('#loginUsername').value.trim());form.append('password',$('#loginPassword').value);authMessage.textContent='Connexion…';authMessage.className='';try{let response=await nativeFetch('/api/auth/login',{method:'POST',body:form}),data=await response.json();if(!response.ok)throw new Error(data.detail||'Connexion refusée');location.reload()}catch(error){authMessage.textContent=error.message;authMessage.className='error'}};
$('#logoutBtn').onclick=async()=>{let response=await fetch('/api/auth/logout',{method:'POST'});if(response.ok)location.reload()};
$('#changeOwnPassword').onclick=async()=>{let form=new FormData();form.append('current_password',$('#currentPassword').value);form.append('new_password',$('#newPassword').value);let response=await fetch('/api/account/password',{method:'POST',body:form}),data=await response.json();authMessage.textContent=response.ok?'Mot de passe remplacé. Reconnexion nécessaire.':data.error||data.detail;authMessage.className=response.ok?'':'error';if(response.ok)setTimeout(()=>location.reload(),900)};

async function loadUsers(){if(document.body.dataset.role!=='admin')return;let response=await fetch('/api/admin/users');if(!response.ok)return;let data=await response.json();$('#userAdminList').innerHTML=data.items.map(user=>`<div class="user-admin-row"><span><b>${esc(user.username)}</b><small>${user.role==='admin'?'Administrateur':'Utilisateur'} · ${user.enabled?'actif':'désactivé'}</small></span><div class="user-admin-actions"><button type="button" data-user-toggle="${user.id}" data-enabled="${user.enabled}">${user.enabled?'Désactiver':'Réactiver'}</button><button type="button" data-user-password="${user.id}">Mot de passe</button></div></div>`).join('');$$('[data-user-toggle]').forEach(button=>button.onclick=async()=>{let form=new FormData();form.append('enabled',button.dataset.enabled!=='true');let response=await fetch(`/api/admin/users/${button.dataset.userToggle}/enabled`,{method:'POST',body:form}),data=await response.json();if(!response.ok){$('#userAdminMessage').textContent=data.error||data.detail;$('#userAdminMessage').className='error'}await loadUsers()});$$('[data-user-password]').forEach(button=>button.onclick=async()=>{let password=prompt('Nouveau mot de passe (12 caractères minimum) :');if(!password)return;let form=new FormData();form.append('password',password);let response=await fetch(`/api/admin/users/${button.dataset.userPassword}/password`,{method:'POST',body:form}),data=await response.json();$('#userAdminMessage').textContent=response.ok?'Mot de passe remplacé.':data.error||data.detail;$('#userAdminMessage').className=response.ok?'':'error'})}
$('#createUser').onclick=async()=>{let form=new FormData();form.append('username',$('#newUsername').value.trim());form.append('password',$('#newUserPassword').value);form.append('role',$('#newUserRole').value);let response=await fetch('/api/admin/users',{method:'POST',body:form}),data=await response.json();$('#userAdminMessage').textContent=response.ok?'Compte créé.':data.error||data.detail;$('#userAdminMessage').className=response.ok?'':'error';if(response.ok){$('#newUsername').value='';$('#newUserPassword').value='';await loadUsers()}};
loadUsers();
